    const b = new Body(nextId++, 'box');
    b.invMass = 1;
    b.invInertia = 6; // unit cube, mass 1: I = m/6
    b.friction = 0.6;
    b.restitution = 0.1;
    b.linDamp = 0.02;
    b.angDamp = 0.15;
    b.pos.set(PYRAMID_CENTER_X + (i - (count - 1) / 2), 0.5 + row, 0);
    crateStart.push(b.pos.clone());
    crates.push(b);
    world.add(b);
  }
}

