// ------------------------------------------------------------------ game state
let phase: Phase = 'ready';
let pulling = false;
let pullTime = 0;
let pullFrom = 0;
let released = false;
let releaseTime = 0;
let hit = false;
let quietTime = 0;

function setBallAngle(rad: number): void {
  ball.pos.set(PIVOT.x - ROPE_LENGTH * Math.sin(rad), PIVOT.y - ROPE_LENGTH * Math.cos(rad), 0);
  ball.vel.set(0, 0, 0);
  ball.ang.set(0, 0, 0);
}

function currentBallAngle(): number {
  return Math.atan2(PIVOT.x - ball.pos.x, PIVOT.y - ball.pos.y);
}

function resetScene(): void {
  crates.forEach((b, i) => {
    b.pos.copy(crateStart[i]);
    b.quat.identity();
    b.vel.set(0, 0, 0);
    b.ang.set(0, 0, 0);
    b.sleeping = true;
    b.sleepTimer = 0;
  });
  ball.quat.identity();
  ball.kinematic = true;
  setBallAngle(0);
  world.clearCache();
  pulling = false;
  released = false;
  hit = false;
  quietTime = 0;
  releaseTime = 0;
  phase = 'ready';
}

function startSwing(): void {
  if (pulling) return;
  pulling = true;
  pullTime = 0;
  pullFrom = currentBallAngle();
  released = false;
  hit = false;
  quietTime = 0;
  ball.kinematic = true;
  phase = 'swinging';
}

function simStep(): void {
  if (pulling) {
    pullTime += DT;
    const u = Math.min(pullTime / PULL_DURATION, 1);
    const s = u * u * (3 - 2 * u);
    setBallAngle(pullFrom + (PULL_ANGLE - pullFrom) * s);
    if (u >= 1) {
      pulling = false;
      ball.kinematic = false;
      released = true;
      releaseTime = 0;
    }
  }

  world.step(DT);

  if (released) {
    releaseTime += DT;
    let maxSpeed = 0;
    for (const c of crates) {
      if (!c.sleeping) maxSpeed = Math.max(maxSpeed, c.vel.length());
    }
    if (maxSpeed > 0.5) hit = true;
    quietTime = maxSpeed < 0.15 ? quietTime + DT : 0;
    phase = (hit || releaseTime > 9) && quietTime >= 1.0 ? 'settled' : 'swinging';
  } else if (pulling) {
    phase = 'swinging';
  } else {
    phase = 'ready';
  }
}

